def langford(n=31):
    seq = [0] * (2 * n)
    def place(v):
        if v == 0:
            return True
        d = v + 1
        for i in range(2 * n - d):
            if seq[i] == 0 and seq[i + d] == 0:
                seq[i] = v
                seq[i + d] = v
                if place(v - 1):
                    return True
                seq[i] = 0
                seq[i + d] = 0
        return False
    if place(n):
        return seq
    else:
        return None

