import random
from collections import defaultdict, deque

def has_short_cycle(edges, n=18):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for nei in graph[node]:
                if dist[nei] == -1:
                    dist[nei] = dist[node] + 1
                    parent[nei] = node
                    queue.append(nei)
                elif nei != parent[node]:
                    cycle_len = dist[node] + dist[nei] + 1
                    if cycle_len < 8:
                        return True
        return False

    for v in range(n):
        if bfs(v):
            return True
    return False

# Color classes 0-5:A,6-11:B,12-17:C
possible_edges = [(i,j) for i in range(18) for j in range(i+1,18) if (i//6) != (j//6)]

random.seed(42)
found = False
selected = None
trials = 0
while trials < 10000:
    trials += 1
    selected = random.sample(possible_edges, 29)
    if not has_short_cycle(selected):
        found = True
        break

print("Found:", found, "after", trials, "trials")
if found:
    print("Edges:", sorted(selected))
else:
    print("Not found")

