for i in range(n):
    s.add(And(c[i]>=0, c[i]<=2))
edge_lit = {}
chord_list = []
for i in range(n):
    for j in range(i+1, n):
        diff = min(j-i, n-(j-i))
        if diff == 1:
            edge_lit[(i,j)] = True
            s.add(c[i] != c[j])
        elif 6 <= diff <=9:
            var = Bool(f'e_{i}_{j}')
            edge_lit[(i,j)] = var
            chord_list.append(var)
            s.add(Implies(var, c[i] != c[j]))
        else:
            edge_lit[(i,j)] = False
s.add(Sum([If(v,1,0) for v in chord_list]) >= 9)
def get_lit(u, v):
    if u > v:
        u, v = v, u
    return edge_lit[(u, v)]
for k in range(3,7):
    for comb in itertools.combinations(range(n), k):
        minv = min(comb)
        others = [x for x in comb if x != minv]
        for perm in itertools.permutations(others):
            cycle = [minv] + list(perm)
            if cycle[1] > cycle[-1]: continue
            lits = []
            all_possible = True
            for a, b_idx in zip(cycle, range(1, len(cycle))):
                b = cycle[b_idx]
