                if lit == False:
                    all_possible = False
                    break
                lits.append(lit)
            if not all_possible:
                continue
            lit_last = get_lit(cycle[-1], cycle[0])
            if lit_last == False:
                continue
            lits.append(lit_last)
            s.add(Or([Not(l) for l in lits]))
