import sys
from collections import deque

def compute_girth(n, connections):
    graph = [[] for _ in range(n)]
    for i in range(n):
        for d in connections:
            j = (i + d) % n
            if j not in graph[i]:
                graph[i].append(j)
            if i not in graph[j]:
                graph[j].append(i)
    # now compute girth
    min_g = sys.maxsize
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u] and dist[v] >= 0:
                    cycle = dist[u] + dist[v] + 1
                    if cycle < min_g:
                        min_g = cycle
    return min_g, len([len(neigh) for neigh in graph]) // 2  # also num edges? wait no

