import random
from collections import deque

def is_4_colorable(adj, n):
    cols = [-1]*n
    def bt(v):
        if v==n: return True
        used = set()
        for nei in adj[v]:
            if cols[nei] != -1: used.add(cols[nei])
        for c in range(4):
            if c not in used:
                cols[v] = c
                if bt(v+1): return True
                cols[v] = -1
        return False
    return bt(0)

def build_random_girth():
    n=20
    adj = [[] for _ in range(n)]
    edges_set = set()
    while True:
        candidates = []
        for u in range(n):
            for v in range(u+1,n):
                if v not in adj[u]:
                    dists = [-1]*n
                    dists[u]=0
                    q=deque([u])
                    d_found = 999
                    while q:
                        x = q.popleft()
                        for y in adj[x]:
                            if dists[y]==-1:
                                dists[y]=dists[x]+1
                                if y==v:
                                    d_found = dists[y]
                                    break
                                if dists[y] < 6:
                                    q.append(y)
                        if d_found < 999: break
                    if d_found > 5:
                        candidates.append((u,v))
