def is_valid_graph(adj, n):
    degrees = [len(neighs) for neighs in adj]
    if any(d < 3 or d > 5 for d in degrees):
        return False
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = deque([start])
        visited_edges = set()  # not needed
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < 7:
                        return False
    return True

def generate_random_regular(n=25, d=4, max_attempts=500):
    for attempt in range(max_attempts):
        stubs = list(range(n)) * d
        random.shuffle(stubs)
        adj = [set() for _ in range(n)]
        i = 0
        success = True
        while i < len(stubs) - 1:
            u = stubs[i]
            v = stubs[i + 1]
            if u == v or v in adj[u]:
                # Try to swap v with a later one
                swapped = False
                for j in range(i + 2, len(stubs), 1):
                    if j % 2 == 0: continue  # to avoid too much
                    w = stubs[j]
                    if u != w and w not in adj[u] and v != stubs[j-1] and stubs[j-1] != w and w not in adj[stubs[j-1]]:
                        stubs[i+1], stubs[j] = w, v
                        swapped = True
                        break
                if not swapped:
                    success = False
                    break
                continue
            adj[u].add(v)
            adj[v].add(u)
            i += 2
        if not success or any(len(adj[k]) != d for k in range(n)):
            continue
        adj_list = [sorted(list(s)) for s in adj]
        if is_valid_graph(adj_list, n):
            edges = []
            for u in range(n):
                for v in adj_list[u]:
                    if u < v:
                        edges.append((u, v))
            return sorted(edges)
    return None

