import random
from collections import deque

def has_short_cycle(adj, g=6):
    n = len(adj)
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = deque([start])
        while q:
            u = q.popleft()
            if dist[u] > g // 2:
                continue
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < g:
                        return True
    return False

def generate_graph(n=23, d=4, max_tries=10000):
    for _ in range(max_tries):
        stubs = list(range(n)) * d
        random.shuffle(stubs)
        adj = [set() for _ in range(n)]
        valid = True
        for i in range(0, n * d, 2):
            if i+1 >= n*d:
                break
            u = stubs[i]
            v = stubs[i + 1]
            if u == v or v in adj[u]:
                valid = False
                break
            adj[u].add(v)
            adj[v].add(u)
        if valid:
            adj_list = [sorted(list(s)) for s in adj]
            # check degrees just in case
            if all(len(a) == d for a in adj_list):
                if not has_short_cycle(adj_list, 6):
                    edges = []
                    for u in range(n):
                        for v in adj_list[u]:
                            if u < v:
                                edges.append((u, v))
                    return edges
    return None

result = generate_graph()
print(result if result else "None found")

import random
from collections import deque

def bfs_girth(adj, n, max_girth=6):
    for s in range(n):
        dist = [-1] * n
        dist[s] = 0
        q = deque([s])
        parent = [-1] * n
        while q:
            u = q.popleft()
            if dist[u] > max_girth // 2 + 1:
                break
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    if dist[u] + dist[v] + 1 < max_girth:
                        return False
    return True

def random_regular_graph(n, d, max_attempts=500):
    for attempt in range(max_attempts):
        adj = [[] for _ in range(n)]
        for u in range(n):
            while len(adj[u]) < d:
                v = random.randint(0, n-1)
                if v != u and v not in adj[u] and len(adj[v]) < d and u not in adj[v]:
                    adj[u].append(v)
                    adj[v].append(u)
        if all(len(adj[i]) == d for i in range(n)):
            if bfs_girth(adj, n, 6):
                edges = []
                for u in range(n):
                    for v in adj[u]:
                        if u < v:
                            edges.append((u, v))
                return sorted(edges)
    return None

